// Land documents in the member portal: how an uploaded patta / land survey extract is read,
// checked, and reconciled with the register. Pure: no I/O. The PDF text itself is pulled out
// by netlify/functions/lib/land-doc-read.ts; the writes are in
// netlify/functions/members-land-extract-background.mts.
//
// No AI is involved and nothing leaves our systems. The two Tamil Nadu e-Services extracts
// members download (the Integrated Land Record / A-Register, and the chitta, "நில உரிமை
// விபரங்கள்") are generated by the same software every time, so a fixed template reads them.
// A file that doesn't match a template (a photo, a scan, a changed layout) is not guessed at:
// it goes to the core team with the file attached.
//
// What the templates can and can't read (checked against real downloads):
//   * survey no., patta no., area, and the land reference number: plain digits, always readable.
//   * owner names: readable in English on a chitta; on the A-Register they are Tamil text with
//     lost vowel signs, so they are NOT read. Owners are then "unknown", which never blocks
//     verifying a record the register already holds (the register already says whose it is),
//     but a new entry is always held for the core team, who see the file.
//
// Every decision (verify, create, send to the core team) is made by the fixed rules below.
//
// Tamil Nadu extracts print land area as "hectare - are" (1 are = 100 sq m), e.g.
// "0.0-35.22" = 0 ha 35.22 ares = 0.3522 ha. Don't confuse it with the neighbouring
// "தீர்வை" (assessment, in rupees) column. 0.0288 ha = 3,100 sq ft, which is the usual
// TVC house plot.

// A real patta / chitta PDF is 50-130 KB, so a PDF over 1 MB is not one. Photos and scans are
// larger, and are only ever read by a person.
export const MAX_PDF_BYTES = 1_000_000;
export const MAX_IMAGE_BYTES = 3_000_000;
// Everything a household has stored (replaced or removed files don't count).
export const MAX_HOUSEHOLD_BYTES = 20_000_000;
export const NOT_A_LAND_PDF = "That PDF doesn't look like a patta or chitta from eservices.tn.gov.in, so we haven't kept it. Download the original from eservices.tn.gov.in and upload that. If you only have a paper copy, upload a clear photo of it instead.";
export const WRONG_CARD = {
  farm: 'These survey numbers are already on your Farm land card, so this looks like a farm land document. Please upload it from the Farm land card instead.',
  house: 'These survey numbers are already on your House plot card, so this looks like a house plot document. Please upload it from the House plot card instead.',
};
export const ALLOWED_MIME = ['application/pdf', 'image/jpeg', 'image/png'];
export const LAND_TYPES = ['farm', 'house'];
export const MAX_UPLOADS_PER_DAY = 10; // per household, to bound the cost of reading files

const HA_TO_ACRES = 2.471054;
const HA_TO_SQFT = 107639.104;

// ---- reading the two templates ------------------------------------------------

const AREA_PAIR = /(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)/g;
const SURVEY = String.raw`\d+(?:\/[0-9A-Za-z]+)+`;
// Control characters the PDF font leaves in the text layer.
const stripControls = (t) => t.replace(/[\u0000-\u0009\u000b-\u001f]/g, '');

// pages: the text of each page, in reading order. Returns the raw record shape that
// normalizeExtraction() checks, or null when the text matches neither template.
export function parseLandPdfText(pages) {
  const text = pages.map(stripControls).join('\n');

  // Integrated Land Record: one row per survey number, e.g.
  //   "450/3C 0 P <tamil> - 0 8-8-2 0.76 0.0-35.22 0.76 1954"
  //    survey, old survey, zone, ..., soil code, assessment, AREA (ha-ares), total assessment, patta
  if (/Integrated Land Record/i.test(text)) {
    const row = new RegExp(String.raw`(${SURVEY})\s+\d+\s+[A-Z]\b[^\n]*?\b\d-\d-\d\s+[\d.]+\s+(\d+(?:\.\d+)?)-(\d+(?:\.\d+)?)\s+[\d.]+\s+(\d+)\b`, 'g');
    const records = [...text.matchAll(row)].map((m) => ({ survey_no: m[1], area_hectares: Number(m[2]), area_ares: Number(m[3]), patta_no: m[4] }));
    if (records.length === 0) return null;
    return { document_type: 'land_record', records, owners: [] };
  }

  // Chitta ("நில உரிமை விபரங்கள்"): the land reference in the footer, owners (English, when the
  // registry typed them in English) before the land table, one row per survey number whose area
  // columns (dry / wet / other) are summed. Detected by the e-Services address and that reference,
  // NOT by Tamil words: a PDF saved from Safari or a phone scrambles the Tamil glyphs, but the
  // digits, English words and punctuation come through unchanged.
  const reference = text.match(/\b(?:[A-Z]\/)?\d{1,2}\/\d{1,2}\/\d{3}\/\d{4,6}\/\d{4,6}\b/)?.[0] ?? null;
  if (/eservices\.tn\.gov\.in/i.test(text) && reference) {
    // The patta number is the second-from-last part of the reference (".../01954/80169" = 1954).
    const patta = pattaFromReference(reference);
    const owners = [...text.matchAll(/^\s*\d+\.\s+([A-Za-z][A-Za-z .]*?)\s+[^\u0000-\u007f]/gm)].map((m) => m[1].trim());
    const records = [];
    for (const m of text.matchAll(/^(\d+)\s+(\d+[A-Za-z]*)\s+(.+)$/gm)) {
      const pairs = [...m[3].matchAll(AREA_PAIR)];
      if (pairs.length === 0) continue; // not a land row (a date, a page number)
      const ha = pairs.reduce((n, p) => n + Number(p[1]), 0);
      const ares = pairs.reduce((n, p) => n + Number(p[2]), 0);
      records.push({ survey_no: `${m[1]}/${m[2]}`, patta_no: patta, area_hectares: ha, area_ares: ares, reference_no: reference });
    }
    if (records.length === 0 || !patta) return null;
    // The table ends with a totals row ("0 - 51.81 1.21"). If the rows read don't add up to it,
    // something was misread: don't trust the reading, let a person look.
    const total = text.match(/^\s*(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)\s+\d+(?:\.\d+)?\s*$/m);
    if (total) {
      const sum = records.reduce((n, r) => n + r.area_hectares * 100 + r.area_ares, 0);
      if (Math.abs(sum - (Number(total[1]) * 100 + Number(total[2]))) > 0.015) return null;
    }
    return { document_type: 'land_record', records, owners };
  }
  return null;
}

// ---- normalising what was read -----------------------------------------

// Not an error the member must fix: the file goes to the core team (see the background function).
export const UNREADABLE = "We couldn't read this file automatically, so the core team will check it by hand.";

const clean = (v) => (typeof v === 'string' ? v.trim().replace(/\s+/g, ' ') : '');
const finite = (v) => (typeof v === 'number' && Number.isFinite(v) && v >= 0 ? v : null);
const r = (n, places) => Math.round(n * 10 ** places) / 10 ** places;

// "450 / 3c" -> "450/3C". Compared, never displayed back (we show what is recorded).
export function normalizeSurveyNo(value) {
  return clean(String(value ?? '')).toUpperCase().replace(/\s+/g, '').replace(/[\\-]/g, '/').replace(/\/{2,}/g, '/').replace(/^\/|\/$/g, '');
}

// A register entry may hold several survey numbers ("450/3C, 450/5B"); compare each.
function surveyTokens(value) {
  return String(value ?? '').split(/[,;&]| and /i).map(normalizeSurveyNo).filter(Boolean);
}

export function pattaDigits(value) {
  const m = String(value ?? '').match(/\d+/);
  return m ? String(parseInt(m[0], 10)) : null;
}

// "P/31/12/081/02812/90143" -> "2812": the patta number sits second from the end, as in
// scripts/lib/member-import.mjs.
function pattaFromReference(reference) {
  const parts = String(reference ?? '').split('/');
  return parts.length >= 2 ? pattaDigits(parts[parts.length - 2]) : null;
}

export function areaFromHaAres(hectares, ares) {
  const ha = finite(hectares);
  const are = finite(ares);
  if (ha == null && are == null) return null;
  const totalHa = (ha ?? 0) + (are ?? 0) / 100;
  return { hectares: r(totalHa, 4), acres: r(totalHa * HA_TO_ACRES, 2), sqFt: r(totalHa * HA_TO_SQFT, 0) };
}

// raw: parseLandPdfText()'s result. Returns { ok: true, extraction } or { ok: false, error }
// where error is safe to show the member.
export function normalizeExtraction(raw) {
  if (raw === null || typeof raw !== 'object' || raw.document_type !== 'land_record') return { ok: false, error: UNREADABLE };
  const records = (Array.isArray(raw.records) ? raw.records : [])
    .map((rec) => {
      const surveyNo = normalizeSurveyNo(rec?.survey_no);
      if (!surveyNo || !/\d/.test(surveyNo)) return null;
      const area = areaFromHaAres(rec.area_hectares, rec.area_ares);
      const referenceNo = clean(rec.reference_no) || null;
      return {
        surveyNo,
        pattaNo: pattaDigits(rec.patta_no) ?? (referenceNo ? pattaFromReference(referenceNo) : null),
        referenceNo,
        areaHectares: area?.hectares ?? null,
        areaAcres: area?.acres ?? null,
        areaSqFt: area?.sqFt ?? null,
      };
    })
    .filter(Boolean);
  if (records.length === 0) return { ok: false, error: UNREADABLE };
  // Repeated survey numbers in one file are one record.
  const seen = new Set();
  const unique = records.filter((rec) => !seen.has(rec.surveyNo) && seen.add(rec.surveyNo));
  const owners = (Array.isArray(raw.owners) ? raw.owners : []).map(clean).filter(Boolean).slice(0, 12);
  return {
    ok: true,
    extraction: {
      district: clean(raw.district) || null,
      taluk: clean(raw.taluk) || null,
      village: clean(raw.village) || null,
      printedDate: clean(raw.printed_date) || null,
      digitallySigned: raw.digitally_signed === true,
      owners,
      records: unique.slice(0, 12),
    },
  };
}

// ---- replacing an earlier upload --------------------------------------------

// The survey numbers a reading covers, as one comparable string ("450/5B" or "450/3C|450/5B").
// extraction: normalizeExtraction().extraction, or a document's stored `extracted`.
export function surveyKey(extraction) {
  const nos = (extraction?.records ?? []).map((r) => r?.surveyNo).filter(Boolean);
  return nos.length ? [...new Set(nos)].sort().join('|') : null;
}

// A new upload replaces the household's earlier documents that it duplicates: the very same file,
// or one for the same survey numbers and the same kind of land (a fresh download of the same
// extract is a different file, since e-Services prints the time on it). The old file, its outline
// and its row are removed, and the new one is read as if it were a first upload. A document
// still being read is left alone (the reader is working on it).
//   existing: this household's rows { id, sha256, land_type, status, created_at, extracted }
export function documentsReplacedBy({ sha256, landType, key, existing, now = Date.now(), staleMs = 10 * 60 * 1000 }) {
  return existing.filter((d) => {
    if (d.status === 'processing' && now - Date.parse(d.created_at) <= staleMs) return false;
    if (d.sha256 === sha256) return true;
    return Boolean(key) && d.land_type === landType && surveyKey(d.extracted) === key;
  });
}

// A farm patta and a house patta are the same kind of PDF, so the file can't say which card it was
// meant for. The household's own registers can: if none of the document's survey numbers is in the
// register of the card used, but some are in the other one, it was uploaded on the wrong card.
// Returns { actual: 'farm' | 'house' } for that case, otherwise null.
//   farmRows / houseRows: this household's records, { survey_no }
export function landTypeMismatch({ landType, extraction, farmRows, houseRows }) {
  const held = (rows) => new Set(rows.flatMap((row) => surveyTokens(row.survey_no)));
  const farm = held(farmRows);
  const house = held(houseRows);
  const [own, other] = landType === 'house' ? [house, farm] : [farm, house];
  const surveyNos = extraction.records.map((rec) => rec.surveyNo);
  if (surveyNos.some((n) => own.has(n))) return null;
  return surveyNos.some((n) => other.has(n)) ? { actual: landType === 'house' ? 'farm' : 'house' } : null;
}

// ---- names -------------------------------------------------------------------

const nameTokens = (name) => clean(name).toLowerCase().replace(/[^a-z\s]/g, ' ').split(/\s+/).filter((t) => t.length > 1);

function editDistanceAtMostOne(a, b) {
  if (a === b) return true;
  if (Math.abs(a.length - b.length) > 1) return false;
  let i = 0;
  while (i < a.length && i < b.length && a[i] === b[i]) i++;
  if (a.length === b.length) return a.slice(i + 1) === b.slice(i + 1);
  return a.length < b.length ? a.slice(i) === b.slice(i + 1) : a.slice(i + 1) === b.slice(i);
}

// Tamil to English transliteration varies (Sharath / Sarath), so allow one letter of slack on
// words of four or more letters.
const sameWord = (a, b) => a === b || (a.length >= 4 && b.length >= 4 && editDistanceAtMostOne(a, b));

// A person matches an owner when every word of the shorter name appears in the longer one
// ("Deepa Alex" in "DEEPA ALEX"; "Sharath Jeppu" in "SHARATH KUMAR JEPPU").
export function namesMatch(personName, ownerName) {
  const a = nameTokens(personName);
  const b = nameTokens(ownerName);
  if (a.length === 0 || b.length === 0) return false;
  const [short, long] = a.length <= b.length ? [a, b] : [b, a];
  return short.every((t) => long.some((u) => sameWord(t, u)));
}

export function ownerMatchesHousehold(owners, peopleNames) {
  return peopleNames.some((p) => owners.some((o) => namesMatch(p, o)));
}

// ---- reconciling with the register -------------------------------------------

function sameArea(recordedHa, recordedAcres, recordedSqFt, doc, landType) {
  if (landType === 'house') {
    if (recordedSqFt == null || doc.areaSqFt == null) return true;
    return Math.abs(recordedSqFt - doc.areaSqFt) <= Math.max(10, doc.areaSqFt * 0.01);
  }
  if (recordedHa != null && doc.areaHectares != null) return Math.abs(recordedHa - doc.areaHectares) <= Math.max(0.0005, doc.areaHectares * 0.01);
  if (recordedAcres != null && doc.areaAcres != null) return Math.abs(recordedAcres - doc.areaAcres) <= 0.01 + doc.areaAcres * 0.01;
  return true; // nothing recorded to compare with: it is a gap to fill, not a disagreement
}

// extraction: normalizeExtraction().extraction
// landType:   'farm' | 'house' (what the member said the file is)
// household:  { peopleNames: string[] }
// existing:   this household's rows of that kind, in the table's column names (member_plots / member_house_pattas)
// heldElsewhere: Set of normalized survey numbers on OTHER households' records of that kind
// autoVerify: true only for a PDF; a photo or scan is never accepted without the core team
//
// Returns one item per survey number:
//   outcome 'verified'  the register has it and the document agrees: mark it verified
//                       (blank fields are filled in from the document; filled-in values are never overwritten)
//   outcome 'pending'   the register has no such entry: add it as pending_review (the core team confirms it)
//   outcome 'check'     the register has it and nothing disagrees, but a photo/scan can't verify it alone
//   outcome 'mismatch'  the register has it and the document disagrees (see `differences`): nothing changes
//   outcome 'conflict'  another household's record holds this survey number: nothing is created
// `ownerMatch` is false when owners are named and none is in the household, null when the
// template couldn't read any names.
export function reconcile({ extraction, landType, household, existing, heldElsewhere, autoVerify }) {
  // null = the template can't read owner names (A-Register): unknown, not a mismatch.
  const ownerMatch = extraction.owners.length > 0 ? ownerMatchesHousehold(extraction.owners, household.peopleNames) : null;
  const items = extraction.records.map((doc) => {
    const base = {
      surveyNo: doc.surveyNo,
      pattaNo: doc.pattaNo,
      referenceNo: doc.referenceNo,
      areaHectares: doc.areaHectares,
      areaAcres: doc.areaAcres,
      areaSqFt: doc.areaSqFt,
      ownerMatch,
    };
    const match = existing.find((row) => surveyTokens(row.survey_no).includes(doc.surveyNo));
    if (!match) {
      if (heldElsewhere.has(doc.surveyNo)) return { ...base, outcome: 'conflict', differences: [] };
      return { ...base, outcome: 'pending', differences: [] };
    }

    const differences = [];
    const recordedPatta = pattaDigits(match.patta_no) ?? (match.reference_no ? pattaFromReference(match.reference_no) : null);
    if (recordedPatta && doc.pattaNo && recordedPatta !== doc.pattaNo) differences.push({ field: 'patta_no', recorded: String(recordedPatta), document: doc.pattaNo });
    if (!sameArea(num(match.area_hectares), num(match.area_acres), num(match.area_sq_ft), doc, landType)) {
      differences.push(landType === 'house'
        ? { field: 'area_sq_ft', recorded: String(num(match.area_sq_ft)), document: String(doc.areaSqFt) }
        : { field: 'area', recorded: String(num(match.area_hectares) ?? `${num(match.area_acres)} ac`), document: `${doc.areaHectares} ha` });
    }
    if (ownerMatch === false) differences.push({ field: 'owners', recorded: 'household members', document: 'names on the document' });

    // Only blanks are filled from the document.
    const fill = {};
    if (!match.patta_no && doc.pattaNo) fill.patta_no = doc.pattaNo;
    if (!match.reference_no && doc.referenceNo) fill.reference_no = doc.referenceNo;
    if (landType === 'house') {
      if (match.area_sq_ft == null && doc.areaSqFt != null) fill.area_sq_ft = doc.areaSqFt;
    } else {
      if (match.area_hectares == null && doc.areaHectares != null) fill.area_hectares = doc.areaHectares;
      if (match.area_acres == null && doc.areaAcres != null) fill.area_acres = doc.areaAcres;
    }
    if (!match.settlement && extraction.village) fill.settlement = extraction.village;

    return {
      ...base,
      // A record the member added from a document is waiting for the core team: uploading the
      // same document again must not be a way to verify it.
      outcome: differences.length > 0 ? 'mismatch' : autoVerify && match.verification !== 'pending_review' ? 'verified' : 'check',
      recordId: match.id,
      differences,
      fill,
    };
  });
  return items;
}

const num = (v) => (v == null ? null : Number(v));

// The status of the whole document, from its items: 'needs_review' while any item still waits
// for the core team (a new record is always one of them; a decision from admins clears it),
// otherwise 'applied'.
export function documentStatus(items) {
  const waiting = items.some((i) => ['pending', 'mismatch', 'check', 'conflict'].includes(i.outcome) && !i.decision);
  return waiting ? 'needs_review' : 'applied';
}

// The row to add for an item with outcome 'pending', in the table's column names.
export function newRecordColumns(item, landType, extraction, householdId, documentId) {
  const common = {
    household_id: householdId,
    patta_no: item.pattaNo,
    reference_no: item.referenceNo,
    survey_no: item.surveyNo,
    settlement: extraction.village,
    verification: 'pending_review',
    source_document_id: documentId,
  };
  return landType === 'house'
    ? { ...common, area_sq_ft: item.areaSqFt }
    : { ...common, area_hectares: item.areaHectares, area_acres: item.areaAcres };
}

// What the core team's approval writes to the record behind an item: the document's values
// where the register differs or is blank, plus the verification marks.
export function approvalColumns(item, landType, documentId, now) {
  const cols = { patta_no: item.pattaNo, reference_no: item.referenceNo };
  if (landType === 'house') cols.area_sq_ft = item.areaSqFt;
  else Object.assign(cols, { area_hectares: item.areaHectares, area_acres: item.areaAcres });
  // Never overwrite a value with null: a document that lacks a field says nothing about it.
  for (const k of Object.keys(cols)) if (cols[k] == null) delete cols[k];
  return { ...cols, verification: 'verified', verified_at: now, verification_source: 'staff', source_document_id: documentId };
}

// A short line a member can read, for a document's outcome. No names or numbers of other people.
export function memberSummary(status, items, error) {
  if (status === 'processing') return 'Reading your document…';
  if (status === 'failed') return error || "We couldn't use that file.";
  if (status === 'needs_review' && items.length === 0) return UNREADABLE;
  // A decision from the core team replaces the outcome the reader reached.
  const open = items.filter((i) => !i.decision);
  const count = (o) => open.filter((i) => i.outcome === o).length;
  const approved = items.filter((i) => i.decision === 'approved').length;
  const rejected = items.filter((i) => i.decision === 'rejected').length;
  const parts = [];
  const verified = count('verified') + approved;
  if (verified) parts.push(`${verified} record${verified === 1 ? '' : 's'} verified`);
  const waiting = count('pending');
  if (waiting) parts.push(`${waiting} new record${waiting === 1 ? '' : 's'} added, waiting for the core team to confirm`);
  const staff = count('mismatch') + count('check') + count('conflict');
  if (staff) parts.push(`${staff} sent to the core team to check`);
  if (rejected) parts.push(`${rejected} record${rejected === 1 ? ' was' : 's were'} not accepted by the core team. You can upload the right document again, or ask the core team why`);
  return parts.join('; ') || 'Done.';
}
